import re
import numpy as np

try:
    import faiss
except ImportError:
    faiss = None

# Create 5 facts about a topic
facts = [
    "Python was created by Guido van Rossum and first released in 1991.",
    "Python uses indentation to define code blocks instead of braces.",
    "The Python Package Index (PyPI) hosts hundreds of thousands of third-party packages.",
    "Python lists are mutable, ordered collections that can hold items of any type.",
    "The Global Interpreter Lock (GIL) allows only one thread to execute Python bytecode at a time.",
]

STOPWORDS = {
    "a", "an", "and", "are", "as", "at", "by", "can", "does", "do", "how", "in", "is",
    "it", "of", "on", "only", "or", "the", "that", "to", "was", "what", "when", "who",
    "any", "first", "one",
}


def tokenize(text: str):
    return [t for t in re.findall(r"[a-z0-9]+", text.lower()) if t not in STOPWORDS]


# Offline vocabulary-based embedding (no API key needed), L2-normalised
vocab = {}
for fact in facts:
    for tok in tokenize(fact):
        vocab.setdefault(tok, len(vocab))
DIM = len(vocab)


def embed(text: str) -> np.ndarray:
    vec = np.zeros(DIM, dtype="float32")
    for tok in tokenize(text):
        if tok in vocab:
            vec[vocab[tok]] += 1.0
    norm = np.linalg.norm(vec)
    return vec / norm if norm else vec


# Embed and store
matrix = np.vstack([embed(f) for f in facts]).astype("float32")
index = None
if faiss is not None:
    index = faiss.IndexFlatIP(DIM)
    index.add(matrix)


def search(query_vec: np.ndarray, k: int):
    if index is not None:
        _, ids = index.search(query_vec.reshape(1, -1), k)
        return [int(i) for i in ids[0] if i >= 0]
    scores = matrix @ query_vec
    return [int(i) for i in np.argsort(-scores, kind="stable")[:k]]


def ask(question: str) -> str:
    """Retrieve relevant facts and format as LLM context."""
    ids = search(embed(question), 2)
    context = "\n".join(f"- {facts[i]}" for i in ids)
    return f"Context:\n{context}\n\nQuestion: {question}\nAnswer using only the context above."


prompt = ask("Who created Python and how does it define code blocks?")
if prompt.count("\n- ") + prompt.startswith("- ") >= 2:
    print("(Formatted context with relevant facts for the question)")
